"""Build the files Elementor's icon picker needs from core/kit/icons.json.

icons.css: one mask-image class per icon (.wpei-<name>), so the icons also work as
an Elementor icon library tab. icons-elementor.json: the icon names for that tab.
Run after editing icons.json: python3 tools/kit/icons.py
"""
import json
import pathlib
import urllib.parse

kit = pathlib.Path(__file__).resolve().parents[2] / 'core' / 'kit'
icons = json.loads((kit / 'icons.json').read_text())
css = [
    '/* Generated by tools/kit/icons.py from icons.json. Do not edit. */',
    '.wpei { display: inline-block; width: 1em; height: 1em; background: currentColor; vertical-align: -.125em;'
    ' -webkit-mask: var(--wpei) center / contain no-repeat; mask: var(--wpei) center / contain no-repeat; }',
]
for name, body in icons.items():
    svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#000" stroke-width="2"'
           ' stroke-linecap="round" stroke-linejoin="round">' + body + '</svg>')
    css.append('.wpei-%s { --wpei: url("data:image/svg+xml,%s"); }' % (name, urllib.parse.quote(svg.replace('"', "'"), safe=" =:/'-.,")))
(kit / 'icons.css').write_text('\n'.join(css) + '\n')
(kit / 'icons-elementor.json').write_text(json.dumps({'icons': list(icons)}) + '\n')
print(len(icons), 'icons')
